// PWA manifest. Next.js serves this at /manifest.webmanifest and the
// browser uses it when the user adds the site to their home screen.
// The icon URLs resolve to the images generated by /app/icon.tsx — the
// "any" purpose covers the regular launcher icon; "maskable" tells
// Android it can crop safely for adaptive icons.

import type { MetadataRoute } from "next";

export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Sphere of Kings",
    short_name: "Sphere of Kings",
    description:
      "Spherical strategy games — Royal Checkers, Imperial Kings, and more. The companion app to the Sphere of Kings 7-in-1 board game.",
    // The installed app opens on the game home, not the marketing page.
    // `id` pins the app's identity so changing start_url later doesn't
    // make browsers treat it as a different app.
    id: "/play",
    start_url: "/play?source=pwa",
    scope: "/",
    display: "standalone",
    orientation: "any",
    background_color: "#0a0806",
    theme_color: "#0a0806",
    categories: ["games", "entertainment"],
    shortcuts: [
      { name: "Quick match", short_name: "Quick match", url: "/play?source=pwa#online" },
      { name: "Daily puzzle", short_name: "Puzzles", url: "/puzzles?source=pwa" },
      { name: "Your matches", short_name: "Matches", url: "/matches?source=pwa" },
    ],
    icons: [
      {
        src: "/icon",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icon",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
      {
        src: "/apple-icon",
        sizes: "180x180",
        type: "image/png",
      },
    ],
  };
}
